-- Step AZ-3: the two French door drawing templates.
-- Run by Nathan in the Supabase SQL editor. Safe to re-run.
-- Run AFTER sql/step-az1 and sql/step-az2.
--
-- Nathan (13 Oct 2026): doors sold are front doors (open in), French doors
-- (open out), single garden doors / doorsets and stable doors. French doors
-- first, and doors are sold in UTILE and ACCOYA only — never softwood.
--
-- Integrate's own templates, from its Door group "2. Open Out Doors"
-- (docs/integrate-L31115-french-doors.txt):
--
--    26  "Fully Glazed"              1899 x 2199  -> GlazePro "French Doors"
--    16  "French Doors w Fanlight"   1350 x 2599  -> "French Doors With Fanlight"
--
-- Integrate's name for 26 is "Fully Glazed", which says nothing about the
-- window in a template list, so it is named for what it is; 16 keeps
-- Integrate's own name tidied.
--
-- Each tree was GENERATED by the board's own code (buildFrenchDoorFrame), so
-- each template is exactly what the board would build, and assertSaveable
-- passes on it. The geometry is Integrate's:
--
--    26  internal 1805 x 2115   one pair, each leaf 912.5 x 2109   A1 / B1
--    16  internal 1256 x 2515 = 399 + 41 + 2075
--        fanlight 1256 x 399 at A1, pair 638 x 2069 each at A2 / B2
--
-- A leaf is NOT half the opening: the two leaves LAP 27 mm at the meeting
-- stile, so each is (internal - 1 - 1 - gap 5 + overlap 27) / 2. Sections are
-- 110 / 110 / 110 with a 163 bottom rail (170 external), stepped, which are
-- the TEMPLATE's values — the profile does not hold the bottom rail.
--
-- The RIGHT leaf is the master, which is Integrate's default; the board
-- offers the other on the pair's panel.
--
-- The fanlight's bottom rail is 62. Integrate's open_out_doors profile holds
-- 58 and its own template drew 86; Nathan decided on 12 Oct that a NEW
-- GlazePro fanlight is 62, so that Integrate's own "reduce to 62mm" warning
-- never fires. It is applied where the fanlight is BUILT, not by
-- applyFanlightBottomRails: that function moves a rail only when it still
-- sits on one of the two casement-profile defaults, and a door profile's 58
-- is neither of them.
--
-- NO stored ironmongery list and NO stored surround list, as every GlazePro
-- template since Step AX: the default rules price both from the drawing
-- (differences 4 and 5 in docs/integrate-differences.md). On a door that is
-- also what Integrate ends up with — it recomputes the surround on save, and
-- the four multipoint-lock parts are added by the allocator, not stored.
--
-- Product and Quantity are both is_required (Step AQ), so the product code is
-- looked up BY LABEL and the script fails loudly rather than writing a code
-- that would look set and still fail the check.

BEGIN;

DO $$
DECLARE
  _profile_id bigint;
  _door_code  text;
  _templates  jsonb := '[{"name":"French Doors","sort_order":10,"tree":{"key":"item_rgkhm5l","part_type":"drawingItemPart","values":{"typeOfWork":"complete_new","frameMaterialId":"utile","sashMaterialId":"utile","cillMaterialId":"utile","quantity":1},"children":[{"key":"paint_v5fb3uj","part_type":"paintAndIronmongeryPart","values":{"internalFinish":"clean_white","externalFinish":"clean_white","cillFinish":"clean_white","cutOutBrickReveal":false,"ironmongeryFinish":"PB","isDoorMpls":true},"children":[]},{"key":"notes_bwpriv5","part_type":"notesPart","values":{},"children":[]},{"key":"price_n0tn5bt","part_type":"pricePart","values":{},"children":[]},{"key":"frame_2tgiokr","part_type":"assemblyFramePart","values":{"width":1899,"height":2199,"leftWidth":47,"rightWidth":47,"topHeight":47,"bottomHeight":37,"frameDepth":96,"jambType":"solid_profiled","frameHeadStopSize":20,"frameStileStopSize":20,"cillStopSize":26,"rakeFrame":false,"archHead":false,"toBeReplaced":true},"children":[{"key":"frenchdoor_fjyrku2","part_type":"frenchDoorPart","values":{"casementTypeId":"open_out","thickness":54,"midRail":198,"gapBetweenMeetingStiles":5,"meetingStileOverlap":27,"mechanicalClearanceTop":3,"mechanicalClearanceBottom":3,"mechanicalClearanceLeft":1,"mechanicalClearanceRight":1,"masterLeaf":"right"},"children":[{"key":"frenchdoor_fjyrku2_left","part_type":"leftFrenchDoorLeafPart","values":{"operation":"left_hand_hung","casementTypeId":"open_out","thickness":54,"topHeight":110,"leftWidth":110,"rightWidth":110,"bottomHeight":163,"bottomHeightExternal":170,"btmRailShapeId":"stepped","isMasterLeaf":false,"toBeReplaced":true},"children":[{"key":"frenchdoor_fjyrku2_left_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]},{"key":"frenchdoor_fjyrku2_right","part_type":"rightFrenchDoorLeafPart","values":{"operation":"right_hand_hung","casementTypeId":"open_out","thickness":54,"topHeight":110,"leftWidth":110,"rightWidth":110,"bottomHeight":163,"bottomHeightExternal":170,"btmRailShapeId":"stepped","isMasterLeaf":true,"toBeReplaced":true},"children":[{"key":"frenchdoor_fjyrku2_right_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]}]},{"key":"cill_hohrql9","part_type":"cillPart","values":{"height":37,"depth":145},"children":[]}]}]}},{"name":"French Doors With Fanlight","sort_order":20,"tree":{"key":"item_x1tgwxa","part_type":"drawingItemPart","values":{"typeOfWork":"complete_new","frameMaterialId":"utile","sashMaterialId":"utile","cillMaterialId":"utile","quantity":1},"children":[{"key":"paint_ejuggmt","part_type":"paintAndIronmongeryPart","values":{"internalFinish":"clean_white","externalFinish":"clean_white","cillFinish":"clean_white","cutOutBrickReveal":false,"ironmongeryFinish":"PB","isDoorMpls":true},"children":[]},{"key":"notes_6iows68","part_type":"notesPart","values":{},"children":[]},{"key":"price_qje5479","part_type":"pricePart","values":{},"children":[]},{"key":"frame_6z0q91h","part_type":"assemblyFramePart","values":{"width":1350,"height":2599,"leftWidth":47,"rightWidth":47,"topHeight":47,"bottomHeight":37,"frameDepth":96,"jambType":"solid_profiled","frameHeadStopSize":20,"frameStileStopSize":20,"cillStopSize":26,"rakeFrame":false,"archHead":false,"toBeReplaced":true},"children":[{"key":"trans_b4lk187","part_type":"transomPart","values":{"offset":399,"thicknessInFrame":41,"transomStopSize":18,"startDivider":"0","endDivider":"0"},"children":[]},{"key":"cas_82z0xrm","part_type":"casementSashPart","values":{"operation":"top_hung","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":62,"bottomHeightExternal":69,"btmRailShapeId":"stepped","mechanicalClearanceTop":1,"mechanicalClearanceLeft":1,"mechanicalClearanceRight":1,"mechanicalClearanceBottom":2,"toBeReplaced":true},"children":[{"key":"cas_82z0xrm_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]},{"key":"frenchdoor_e76fexb","part_type":"frenchDoorPart","values":{"casementTypeId":"open_out","thickness":54,"midRail":198,"gapBetweenMeetingStiles":5,"meetingStileOverlap":27,"mechanicalClearanceTop":3,"mechanicalClearanceBottom":3,"mechanicalClearanceLeft":1,"mechanicalClearanceRight":1,"masterLeaf":"right"},"children":[{"key":"frenchdoor_e76fexb_left","part_type":"leftFrenchDoorLeafPart","values":{"operation":"left_hand_hung","casementTypeId":"open_out","thickness":54,"topHeight":110,"leftWidth":110,"rightWidth":110,"bottomHeight":163,"bottomHeightExternal":170,"btmRailShapeId":"stepped","isMasterLeaf":false,"toBeReplaced":true},"children":[{"key":"frenchdoor_e76fexb_left_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]},{"key":"frenchdoor_e76fexb_right","part_type":"rightFrenchDoorLeafPart","values":{"operation":"right_hand_hung","casementTypeId":"open_out","thickness":54,"topHeight":110,"leftWidth":110,"rightWidth":110,"bottomHeight":163,"bottomHeightExternal":170,"btmRailShapeId":"stepped","isMasterLeaf":true,"toBeReplaced":true},"children":[{"key":"frenchdoor_e76fexb_right_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]}]},{"key":"cill_mdvi6na","part_type":"cillPart","values":{"height":37,"depth":145},"children":[]}]}]}}]'::jsonb;
  _row        record;
  _tree       jsonb;
BEGIN
  SELECT id INTO _profile_id FROM public.default_profiles
  WHERE code = 'open_out_doors' AND is_active = TRUE;
  IF _profile_id IS NULL THEN
    RAISE EXCEPTION 'No active default_profiles row with code ''open_out_doors'' — the door profile must exist first';
  END IF;

  SELECT code INTO _door_code FROM public.reference_options
  WHERE category = 'product' AND lower(label) = 'french door' AND is_active
  ORDER BY sort_order LIMIT 1;
  IF _door_code IS NULL THEN
    RAISE EXCEPTION 'No active reference_options row with category ''product'' and label ''French Door'' — run: SELECT code, label FROM reference_options WHERE category = ''product'' ORDER BY sort_order;';
  END IF;

  -- A template that cannot be saved is worse than no template.
  IF NOT EXISTS (
    SELECT 1 FROM part_type_children
    WHERE parent_code = 'frenchDoorPart' AND child_code = 'leftFrenchDoorLeafPart'
  ) THEN
    RAISE EXCEPTION 'Containment for the French door parts is missing — run sql/step-az2-door-containment.sql first';
  END IF;

  -- And a door with no sections prices no timber at all, which would look
  -- like a working template and quote hundreds of pounds short.
  IF NOT EXISTS (
    SELECT 1 FROM parts_catalogue WHERE part_code = 'Utile67x96' AND is_active
  ) THEN
    RAISE EXCEPTION 'The Utile stock sections are missing — run sql/step-az1-utile-section-parts.sql first';
  END IF;

  IF jsonb_array_length(_templates) <> 2 THEN
    RAISE EXCEPTION 'Expected 2 templates in this script, found %', jsonb_array_length(_templates);
  END IF;

  FOR _row IN
    SELECT * FROM jsonb_to_recordset(_templates) AS x(name text, sort_order int, tree jsonb)
  LOOP
    _tree := jsonb_set(_row.tree, '{values,product}', to_jsonb(_door_code), true);

    IF EXISTS (SELECT 1 FROM public.drawing_templates WHERE name = _row.name) THEN
      UPDATE public.drawing_templates
      SET tree = _tree, default_profile_id = _profile_id,
          sort_order = _row.sort_order, updated_at = now()
      WHERE name = _row.name;
      RAISE NOTICE 'Step AZ-3: % updated in place', _row.name;
    ELSE
      INSERT INTO public.drawing_templates
        (name, family, group_name, window_type, default_profile_id, tree, sort_order, is_active)
      VALUES (_row.name, 'door', 'Open Out Doors', 'Door',
              _profile_id, _tree, _row.sort_order, TRUE);
      RAISE NOTICE 'Step AZ-3: % created', _row.name;
    END IF;
  END LOOP;
END $$;

COMMIT;

-- ── Checks ─────────────────────────────────────────────────────────────────

-- 1. The door templates, with Product and Quantity set.
SELECT name, family, group_name, window_type, sort_order, is_active,
       tree #>> '{values,product}'  AS product_code,
       tree #>> '{values,quantity}' AS quantity,
       tree #>> '{values,sashMaterialId}' AS material
FROM   public.drawing_templates
WHERE  family = 'door'
ORDER  BY sort_order;

-- 2. Each template's shape: one pair with two leaves, no mullion, and a
--    transom + fanlight on the second only.
SELECT t.name,
       (SELECT count(*) FROM jsonb_path_query(t.tree, '$.**.part_type ? (@ == "frenchDoorPart")'))            AS pairs,
       (SELECT count(*) FROM jsonb_path_query(t.tree, '$.**.part_type ? (@ == "leftFrenchDoorLeafPart")'))    AS left_leaves,
       (SELECT count(*) FROM jsonb_path_query(t.tree, '$.**.part_type ? (@ == "rightFrenchDoorLeafPart")'))   AS right_leaves,
       (SELECT count(*) FROM jsonb_path_query(t.tree, '$.**.part_type ? (@ == "mullionPart")'))               AS mullions,
       (SELECT count(*) FROM jsonb_path_query(t.tree, '$.**.part_type ? (@ == "transomPart")'))               AS transoms,
       (SELECT count(*) FROM jsonb_path_query(t.tree, '$.**.part_type ? (@ == "casementSashPart")'))          AS fanlights,
       (SELECT jsonb_agg(v) FROM jsonb_path_query(t.tree, '$.**.values.isMasterLeaf') v)                      AS master_flags,
       (SELECT jsonb_agg(v) FROM jsonb_path_query(t.tree, '$.**.values.bottomHeight') v)                      AS bottom_rails,
       (SELECT jsonb_agg(v) FROM jsonb_path_query(t.tree, '$.**.values.meetingStileOverlap') v)               AS overlaps
FROM   public.drawing_templates t
WHERE  t.name IN (
    'French Doors',
    'French Doors With Fanlight'
)
ORDER  BY t.sort_order;

-- 3. Neither template carries a stored surround or ironmongery list, and
--    both are utile. Expect NULL, NULL, utile.
SELECT t.name,
       t.tree #> '{values,surroundLines}' AS surrounds,
       (SELECT jsonb_agg(v) FROM jsonb_path_query(t.tree, '$.**.values.ironmongeryLines') v) AS ironmongery,
       t.tree #>> '{values,sashMaterialId}' AS material
FROM   public.drawing_templates t
WHERE  t.name IN (
    'French Doors',
    'French Doors With Fanlight'
)
ORDER  BY t.sort_order;


